INSERT INTO feature VALUES('presentation-printer','printing','The presentation printer',NULL,'implemented','notable',NULL,'A checked type, a normal form or an elaborated body prints in its surface spelling, and every printed type reads back; a function definition is written whole, `def name(…) -> C { b }`, and a model type as the source writes it, `Model(T) with sort C = A`. A type a top-level type member defines prints by the member''s name, so a shared type writes each name once; a type no name holds prints whole while its spelling stays linear in its distinct nodes, and `?` by the budget past that. A quoted product over values keeps its quote in the explicit form, since an expression reads `#{a, b}` as a tuple.','surface-pretty','crates/surface-pretty/tests/goldens.rs corpus/model/data/quoted-product.gandr corpus/model/records/iterated-pair.gandr',NULL,'#403');
